    47→function DirectionSync() {
    48→  useEffect(() => {
    49→    const apply = (lang: string) => {
    50→      const rtl = lang === "ku" || lang === "ar";
    51→      document.documentElement.dir = rtl ? "rtl" : "ltr";
    52→      document.documentElement.lang = lang;
    53→      localStorage.setItem("linqi_lang", lang);
    54→    };
    55→    apply(i18n.language);
    56→    i18n.on("languageChanged", apply);
    57→    return () => { i18n.off("languageChanged", apply); };
    58→  }, []);
    59→  return null;
    60→}
    61→
    62→function Router() {
    63→  const { user, isLoading, isAdmin } = useAuth();
    64→  const [location] = useLocation();
    65→
    66→  if (location === "/onboarding") {
    67→    return <Register />;
    68→  }
    69→
    70→  if (isLoading) {
    71→    return (
    72→      <div className="min-h-screen bg-slate-900 flex items-center justify-center">
    73→        <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin" />
    74→      </div>
    75→    );
    76→  }
    77→
    78→  if (!user) {
    79→    return <Register />;
    80→  }
    81→
    82→  if (user.role === "supplier") {
    83→    return <SupplierCatalog />;
    84→  }
    85→
    86→  if (user.role === "buyer") {
    87→    return <BuyerDashboard />;
    88→  }
    89→
    90→  if (user.role === "driver") {
    91→    return <DriverDashboard />;
    92→  }
    93→
    94→  return (
