    96→      <Switch>
    97→        <Route path="/" component={Dashboard} />
    98→        <Route path="/products" component={Products} />
    99→        <Route path="/customers" component={Customers} />
   100→        <Route path="/pos" component={POS} />
   101→        <Route path="/sales" component={Sales} />
   102→        <Route path="/history" component={HistoryPage} />
   103→        <Route path="/debts" component={Debts} />
   104→        <Route path="/reports" component={Reports} />
   105→        {isAdmin && <Route path="/users" component={UsersPage} />}
   106→        {!isAdmin && <Route path="/users"><Redirect to="/" /></Route>}
   107→        {isAdmin && <Route path="/master-admin" component={MasterAdminPanel} />}
   108→        {!isAdmin && <Route path="/master-admin"><Redirect to="/" /></Route>}
   109→        <Route component={NotFound} />
   110→      </Switch>
   111→    </Layout>
   112→  );
   113→}
   114→
   115→function App() {
   116→  return (
   117→    <ThemeProvider>
   118→      <QueryClientProvider client={queryClient}>
   119→        <AuthProvider>
   120→          <TooltipProvider>
