   122→            <WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, "")}>
   123→              <Router />
   124→            </WouterRouter>
   125→            <Toaster />
   126→          </TooltipProvider>
   127→        </AuthProvider>
   128→      </QueryClientProvider>
   129→    </ThemeProvider>
   130→  );
   131→}
   132→
   133→export default App;
