          const data = await res.json();
          const addr = data.display_name
            ?? `${lat.toFixed(5)}, ${lng.toFixed(5)}`;
          onChange(addr);
        } catch {
          onChange(`${lat.toFixed(5)}, ${lng.toFixed(5)}`);
        } finally {
          setLoading(false);
        }
      },
      () => {
        setGpsError(t("onboard.gpsDenied"));
        setLoading(false);
      },
      { timeout: 10000, enableHighAccuracy: true }
