/* ─── GPS Address Field ──────────────────────────────────────────────────── */
function GpsAddressField({ label, value, onChange, placeholder }: {
  label: string; value: string; onChange: (v: string) => void; placeholder: string;
}) {
  const { t } = useTranslation();
  const [loading, setLoading] = useState(false);
  const [gpsError, setGpsError] = useState("");
  const [fetchedOk, setFetchedOk] = useState(false);

  const fetchGPS = () => {
    if (!navigator.geolocation) { setGpsError(t("onboard.gpsUnsupported")); return; }
    setLoading(true);
    setGpsError("");
    setFetchedOk(false);
    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        const { latitude: lat, longitude: lng } = pos.coords;
        try {
          const res = await fetch(
            `https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lng}&format=json`
          );
          const data = await res.json();
          const addr = data.display_name ?? `${lat.toFixed(5)}, ${lng.toFixed(5)}`;
          onChange(addr);
          setFetchedOk(true);
          setTimeout(() => setFetchedOk(false), 3500);
        } catch {
          onChange(`${lat.toFixed(5)}, ${lng.toFixed(5)}`);
          setFetchedOk(true);
          setTimeout(() => setFetchedOk(false), 3500);
        } finally {
          setLoading(false);
        }
      },
      () => {
        setGpsError(t("onboard.gpsDenied"));
        setLoading(false);
      },
      { timeout: 10000, enableHighAccuracy: true }
    );
  };

  const btnColor = loading ? "#60A5FA" : fetchedOk ? "#34D399" : "#94A3B8";

  return (
    <div>
      {label && (
        <label className="block text-xs font-semibold mb-1.5 uppercase tracking-wide"
          style={{ color: "#E2E8F0", letterSpacing: "0.06em" }}>
          {label}
        </label>
      )}
      <div className="relative">
        {/* GPS trigger button — interactive, pulsing ring when idle */}
        <motion.button
          type="button"
          onClick={fetchGPS}
          disabled={loading}
          title={t("onboard.gpsBtn")}
          whileHover={!loading ? { scale: 1.15 } : {}}
          whileTap={!loading ? { scale: 0.88 } : {}}
          className="absolute start-0 top-0 bottom-0 px-3 flex items-center justify-center rounded-s-xl z-10 group"
          style={{ color: btnColor, background: "transparent", cursor: loading ? "default" : "pointer" }}
        >
          {/* idle pulse ring */}
          {!loading && !fetchedOk && (
            <motion.span
              className="absolute inset-0 rounded-s-xl pointer-events-none"
              animate={{
                boxShadow: [
                  "inset 0 0 0 0 rgba(59,130,246,0)",
                  "inset 0 0 0 2px rgba(59,130,246,0.25)",
                  "inset 0 0 0 0 rgba(59,130,246,0)",
                ],
              }}
              transition={{ duration: 2.2, repeat: Infinity, ease: "easeInOut" }}
            />
          )}
          <AnimatePresence mode="wait">
            {loading ? (
              <motion.div key="spin"
                initial={{ opacity: 0, scale: 0.6 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.6 }}
                className="w-4 h-4 border-2 rounded-full animate-spin"
                style={{ borderColor: "rgba(99,179,255,0.3)", borderTopColor: "#60A5FA" }}
              />
            ) : fetchedOk ? (
              <motion.div key="ok"
                initial={{ opacity: 0, scale: 0.5 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0 }}
                transition={{ type: "spring", stiffness: 320, damping: 18 }}
              >
                <Check className="w-4 h-4" style={{ color: "#34D399", filter: "drop-shadow(0 0 4px #34D39988)" }} />
              </motion.div>
            ) : (
              <motion.div key="pin"
                initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
              >
                <MapPin
                  className="w-4 h-4 transition-colors duration-200"
                  style={{ color: btnColor }}
                  onMouseEnter={e => { if (!loading) (e.currentTarget as SVGElement).style.color = "#60A5FA"; }}
                  onMouseLeave={e => { if (!loading) (e.currentTarget as SVGElement).style.color = "#94A3B8"; }}
                />
              </motion.div>
            )}
          </AnimatePresence>
        </motion.button>

        <input
          type="text"
          value={value}
          onChange={e => onChange(e.target.value)}
          placeholder={loading ? t("onboard.gpsFetching") : placeholder}
          className="w-full ps-9 pe-3.5 py-2.5 rounded-xl text-sm text-white placeholder-[#94A3B8] outline-none transition-all"
          style={{
            ...glass.input,
            borderRadius: "0.75rem",
            ...(fetchedOk ? { border: "1px solid rgba(52,211,153,0.5)", boxShadow: "0 0 0 3px rgba(52,211,153,0.12)" } : {}),
          }}
          onFocus={e => { e.currentTarget.style.border = glass.inputFocusBorder; e.currentTarget.style.boxShadow = glass.inputFocusShadow; }}
          onBlur={e  => {
            if (fetchedOk) {
              e.currentTarget.style.border = "1px solid rgba(52,211,153,0.5)";
              e.currentTarget.style.boxShadow = "0 0 0 3px rgba(52,211,153,0.12)";
            } else {
              e.currentTarget.style.border = "1px solid rgba(255,255,255,0.12)";
              e.currentTarget.style.boxShadow = "none";
            }
          }}
        />

        {/* scanning strip while loading */}
        <AnimatePresence>
          {loading && (
            <motion.div
              initial={{ scaleX: 0 }} animate={{ scaleX: 1 }} exit={{ opacity: 0 }}
              className="absolute bottom-0 start-0 end-0 h-0.5 rounded-full origin-start"
              style={{ background: "linear-gradient(90deg,#3B82F6,#06B6D4,#3B82F6)" }}
              transition={{ duration: 1.4, repeat: Infinity, repeatType: "reverse" }}
            />
          )}
        </AnimatePresence>
      </div>
      {gpsError && <p className="text-[11px] text-red-400 mt-1">{gpsError}</p>}
    </div>
  );
}

